package br.com.conectatea.vinculo.domain;
import br.com.conectatea.shared.domain.AuditableEntity; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="vinculos_responsaveis_criancas",uniqueConstraints=@UniqueConstraint(columnNames={"responsavel_id","crianca_id"}))
public class VinculoResponsavelCrianca extends AuditableEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="responsavel_id",nullable=false) private Long responsavelId; @Column(name="crianca_id",nullable=false) private Long criancaId; private String parentesco; private boolean principal; @Enumerated(EnumType.STRING) @Column(nullable=false) private StatusVinculo status; @Column(name="data_vinculo") private Instant dataVinculo; @Column(name="data_desvinculo") private Instant dataDesvinculo; protected VinculoResponsavelCrianca(){} public VinculoResponsavelCrianca(Long r,Long c){responsavelId=r;criancaId=c;status=StatusVinculo.VINCULADO;dataVinculo=Instant.now();} public Long getResponsavelId(){return responsavelId;} public Long getCriancaId(){return criancaId;} public StatusVinculo getStatus(){return status;} public void desvincular(){status=StatusVinculo.DESVINCULADO;dataDesvinculo=Instant.now();} }
